#include <cmath>

double d1_of(double s, double k, double r, double sigma, double t) {
    return (std::log(s / k) + (r + sigma * sigma / 2) * t) / (sigma * std::sqrt(t));
}

double norm_pdf(double x) { return std::exp(-x * x / 2) / std::sqrt(2 * M_PI); }

double bs_delta_call(double s, double k, double r, double sigma, double t) {
    return norm_cdf(d1_of(s, k, r, sigma, t));
}

double bs_vega(double s, double k, double r, double sigma, double t) {
    return s * norm_pdf(d1_of(s, k, r, sigma, t)) * std::sqrt(t);
}

double bs_gamma(double s, double k, double r, double sigma, double t) {
    return norm_pdf(d1_of(s, k, r, sigma, t)) / (s * sigma * std::sqrt(t));
}

