widget.solution:
#include <algorithm>
#include <cmath>
#include <stdexcept>

double implied_vol(double price, double s, double k, double r, double t) {
    double floor = std::max(s - k * std::exp(-r * t), 0.0);
    if (price <= floor || price >= s)
        throw std::invalid_argument("no volatility fits this price");
    double lo = 0.0001, hi = 5.0;
    while (hi - lo >= 1e-8) {
        double mid = 0.5 * (lo + hi);
        if (bs_call(s, k, r, mid, t) > price) hi = mid;
        else lo = mid;
    }
    return 0.5 * (lo + hi);
}

